 import { supabase } from '../lib/supabase'

const PAYFAST_MERCHANT_ID = process.env.REACT_APP_PAYFAST_MERCHANT_ID
const PAYFAST_MERCHANT_KEY = process.env.REACT_APP_PAYFAST_MERCHANT_KEY
const MODE = process.env.REACT_APP_PAYFAST_MODE || 'sandbox'

// ✅ CORRECT URLs for PayFast
const PAYFAST_URL = MODE === 'sandbox' 
    ? 'https://sandbox.payfast.co.za/eng/process'
    : 'https://www.payfast.co.za/eng/process'

// Generate unique reference
function generateReference(communityId, userId) {
    const timestamp = Date.now()
    const random = Math.random().toString(36).substring(2, 8)
    return `PF-${communityId.substring(0, 4)}-${userId.substring(0, 4)}-${timestamp}-${random}`
}

// ============================================
// ✅ INITIATE COMMUNITY PAYMENT
// ============================================
export async function initiateCommunityPayment(communityId, userId, amount, itemName) {
    return initiatePayment(communityId, userId, amount, itemName)
}

// ============================================
// ✅ INITIATE PREMIUM SUBSCRIPTION
// ============================================
export async function initiatePremiumSubscription(userId, planId, amount, planName) {
    try {
        // Create payment record in database
        const { data: payment, error } = await supabase
            .from('subscription_payments')
            .insert({
                user_id: userId,
                plan_id: planId,
                amount: amount,
                platform_fee: amount * 0.1, // 10% platform fee
                creator_earnings: amount * 0.9, // 90% to creator
                currency: 'ZAR',
                status: 'pending',
                payment_type: 'premium'
            })
            .select()
            .single()

        if (error) throw error

        // ✅ Build PayFast data
        const payfastData = {
            merchant_id: PAYFAST_MERCHANT_ID,
            merchant_key: PAYFAST_MERCHANT_KEY,
            return_url: process.env.REACT_APP_PAYFAST_RETURN_URL || `${window.location.origin}/payment/success`,
            cancel_url: process.env.REACT_APP_PAYFAST_CANCEL_URL || `${window.location.origin}/payment/cancel`,
            notify_url: process.env.REACT_APP_PAYFAST_NOTIFY_URL || `${window.location.origin}/api/payment/notify`,
            m_payment_id: payment.id,
            amount: amount.toFixed(2),
            item_name: `${planName} Premium Subscription`,
            item_description: `Monthly subscription to ${planName}`,
            custom_str1: 'premium',
            custom_str2: userId,
            email_confirmation: '1',
            confirmation_address: 'info@predictfc.com'
        }

        return {
            success: true,
            paymentId: payment.id,
            payfastData: payfastData,
            payfastUrl: PAYFAST_URL
        }

    } catch (error) {
        console.error('Premium subscription error:', error)
        return {
            success: false,
            error: error.message
        }
    }
}

// ============================================
// ✅ INITIATE PAYMENT (Core Function)
// ============================================
export async function initiatePayment(communityId, userId, amount, itemName) {
    try {
        // Create payment record in database
        const { data: payment, error } = await supabase
            .from('subscription_payments')
            .insert({
                community_id: communityId,
                user_id: userId,
                amount: amount,
                platform_fee: amount / 2,
                creator_earnings: amount / 2,
                currency: 'ZAR',
                status: 'pending'
            })
            .select()
            .single()

        if (error) throw error

        // ✅ Build PayFast data with CORRECT URLs
        const payfastData = {
            merchant_id: PAYFAST_MERCHANT_ID,
            merchant_key: PAYFAST_MERCHANT_KEY,
            return_url: process.env.REACT_APP_PAYFAST_RETURN_URL || `${window.location.origin}/payment/success`,
            cancel_url: process.env.REACT_APP_PAYFAST_CANCEL_URL || `${window.location.origin}/payment/cancel`,
            notify_url: process.env.REACT_APP_PAYFAST_NOTIFY_URL || `${window.location.origin}/api/payment/notify`,
            m_payment_id: payment.id,
            amount: amount.toFixed(2),
            item_name: itemName,
            item_description: `Subscription to ${itemName}`,
            custom_str1: communityId,
            custom_str2: userId,
            email_confirmation: '1',
            confirmation_address: 'info@predictfc.com'
        }

        return {
            success: true,
            paymentId: payment.id,
            payfastData: payfastData,
            payfastUrl: PAYFAST_URL
        }

    } catch (error) {
        console.error('Payment initiation error:', error)
        return {
            success: false,
            error: error.message
        }
    }
}

// ============================================
// ✅ GENERATE PAYFAST FORM
// ============================================
export function generatePayFastForm(payfastData) {
    const formHtml = `
        <form id="payfastForm" method="POST" action="${PAYFAST_URL}">
            ${Object.entries(payfastData).map(([key, value]) => 
                `<input type="hidden" name="${key}" value="${value}" />`
            ).join('')}
        </form>
        <script>document.getElementById('payfastForm').submit();</script>
    `
    return formHtml
}

// ============================================
// ✅ COMPLETE PAYMENT
// ============================================
export async function completePayment(paymentId, communityId, userId) {
    try {
        // Update payment status
        await supabase
            .from('subscription_payments')
            .update({ status: 'success' })
            .eq('id', paymentId)

        // Check if already a member
        const { data: existing } = await supabase
            .from('community_members')
            .select('id')
            .eq('community_id', communityId)
            .eq('user_id', userId)
            .maybeSingle()

        if (existing) {
            return { success: true, alreadyMember: true }
        }

        // Add user as member
        await supabase
            .from('community_members')
            .insert({
                community_id: communityId,
                user_id: userId,
                role: 'member',
                status: 'active',
                expires_at: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString()
            })

        // Update member count
        const { data: communityData } = await supabase
            .from('communities')
            .select('member_count')
            .eq('id', communityId)
            .single()

        await supabase
            .from('communities')
            .update({
                member_count: (communityData?.member_count || 0) + 1
            })
            .eq('id', communityId)

        return { success: true }

    } catch (error) {
        console.error('Error completing payment:', error)
        return {
            success: false,
            error: error.message
        }
    }
}

// ============================================
// ✅ VERIFY PAYMENT
// ============================================
export async function verifyPayment(paymentData) {
    try {
        // Check if payment already processed
        const { data: existing } = await supabase
            .from('subscription_payments')
            .select('status')
            .eq('id', paymentData.m_payment_id)
            .single()

        if (existing && existing.status === 'success') {
            return { success: true, alreadyProcessed: true }
        }

        // Update payment status
        const { error } = await supabase
            .from('subscription_payments')
            .update({
                status: paymentData.payment_status === 'COMPLETE' ? 'success' : 'failed',
                transaction_id: paymentData.pf_payment_id,
                payment_method: paymentData.payment_method || 'payfast'
            })
            .eq('id', paymentData.m_payment_id)

        if (error) throw error

        // If payment successful, add user to community
        if (paymentData.payment_status === 'COMPLETE') {
            await completePayment(
                paymentData.m_payment_id,
                paymentData.custom_str1,
                paymentData.custom_str2
            )
        }

        return {
            success: true,
            paymentStatus: paymentData.payment_status
        }

    } catch (error) {
        console.error('Payment verification error:', error)
        return {
            success: false,
            error: error.message
        }
    }
}

// ============================================
// ✅ GET PAYMENT STATUS
// ============================================
export async function getPaymentStatus(paymentId) {
    try {
        const { data, error } = await supabase
            .from('subscription_payments')
            .select('*')
            .eq('id', paymentId)
            .single()

        if (error) throw error
        return {
            success: true,
            payment: data
        }
    } catch (error) {
        console.error('Error getting payment status:', error)
        return {
            success: false,
            error: error.message
        }
    }
}
